      'secondary': 'Plumber',
      'equipmentTag': 'Painting & Waterproofing',
      'stems': ['paint'],
      'phrases': ['rangwala', 'safediwala', 'rangari', 'chitrakaar', 'vanna poosu', 'rang lagana'],
